package com.booksyde.service;
import com.booksyde.exception.BusinessException;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service public class FileStorageService{private static final Set<String> TYPES=Set.of("application/pdf","application/epub+zip","application/zip","application/x-cbr","application/x-cbz","image/jpeg","image/png","image/webp");private final String base,key;private final long max;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();public FileStorageService(@Value("${booksyde.security.supabase-url}")String url,@Value("${booksyde.storage.supabase-service-role:}")String key,@Value("${booksyde.storage.max-upload-bytes:104857600}")long max){this.base=url.replaceAll("/+$","");this.key=key;this.max=max;}public String upload(String bucket,String path,MultipartFile file){if(key.isBlank())throw new BusinessException("Storage privilegiado não configurado.");if(file.isEmpty()||file.getSize()>max)throw new BusinessException("Arquivo vazio ou acima do limite permitido.");String type=Optional.ofNullable(file.getContentType()).orElse("application/octet-stream");if(!TYPES.contains(type))throw new BusinessException("Tipo de arquivo não permitido.");String clean=sanitize(path);try{var req=HttpRequest.newBuilder(URI.create(base+"/storage/v1/object/"+bucket+"/"+clean)).header("Authorization","Bearer "+key).header("apikey",key).header("Content-Type",type).header("x-upsert","false").POST(HttpRequest.BodyPublishers.ofByteArray(file.getBytes())).build();var res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()/100!=2)throw new BusinessException("Falha no storage ("+res.statusCode()+").");return clean;}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException("Falha ao enviar arquivo.");}}private String sanitize(String p){String x=p.replace('\\','/').replaceAll("(^|/)\\.\\.?(/|$)","/").replaceAll("[^a-zA-Z0-9._/-]","_");while(x.startsWith("/"))x=x.substring(1);if(x.isBlank()||x.contains(".."))throw new BusinessException("Caminho de arquivo inválido.");return x;}}
